      pending: teams.filter((entry2) => isDue(entry2, now)).length,
      lastRefreshAt: this.lastRefreshAt === null ? null : new Date(this.lastRefreshAt).toISOString(),
      detail: writeFailed ? "no se puede escribir en data/v2/teams" : this.lastRoundFailure
